internal static class OfflineTests {
    private const string C="S-1-5-21-101-202-303-1001",B="S-1-5-21-101-202-303-1002",U="S-1-5-21-101-202-303-1003";
    private static readonly DateTime Now=new DateTime(2030,1,1,0,0,30,DateTimeKind.Utc);
    private static readonly List<string> Rows=new List<string>();private static int passed,failed,mutants;private static long points;
    private static void Assert(bool b,string code){if(!b)throw new Rejected(code);}
    private static void Throws(Action f){try{f();}catch(Rejected){return;}throw new Rejected("EXPECTED_REJECTION_MISSING");}
    private static void Case(string name,Action run){try{run();passed++;Rows.Add("{\"name\":\""+name+"\",\"status\":\"PASS\"}");}catch(Exception e){failed++;string code=e is Rejected?e.Message:"REDACTED_"+e.GetType().Name;Rows.Add("{\"name\":\""+name+"\",\"status\":\"FAIL\",\"code\":\""+code+"\"}");}}
    private static Request Request(string client=C,string broker=B,string ui=U,ushort port=54321,string remote="192.0.2.44",ushort remotePort=443,string profile="STRICT_V2RAY_BROKER",string provenance="SYNTHETIC",string host=null,string inventory=null,Guid? owner=null,DateTime? observed=null,DateTime? expires=null){return new Request(owner??new Guid("11111111-1111-4111-8111-111111111111"),host??new string('a',64),inventory??new string('b',64),client,broker,ui,port,remote,remotePort,observed??Now.AddSeconds(-30),expires??Now.AddMinutes(1),profile,provenance);}
    private static Filter Copy(Filter f,IEnumerable<Condition> conditions=null,uint? action=null,uint? flags=null,Guid? key=null,Guid? provider=null,ulong? weight=null,int? family=null){return new Filter(key??f.Key,provider??f.Provider,f.SubLayer,f.Role,family??f.Family,action??f.Action,flags??f.Flags,weight??f.Weight,conditions??f.Conditions);}
    private static Policy Mutate(Policy p,int i,Func<Filter,Filter> change){var fs=p.Filters.ToArray();fs[i]=change(fs[i]);return new Policy(p.Request,p.Provider,p.SubLayer,fs);}
    // Independent behavioral oracle: direct endpoint equality, not a transcription of predicates.
    private static int Expected(Request r,Packet x){if(x.Sid!=r.ClientSid&&x.Sid!=r.BrokerSid)return 0;bool client=x.Sid==r.ClientSid;var address=String.Join(".",new[]{x.Address>>24,(x.Address>>16)&255,(x.Address>>8)&255,x.Address&255});ushort port=client?r.LocalPort:r.RemotePort;return x.Family==4&&x.Protocol==6&&address==(client?"127.0.0.1":r.Remote)&&x.Port==port?0:1;}
    private static bool OracleDetects(Policy p,Packet x){return PredicateInterpreter.Matches(p,x)!=Expected(p.Request,x);}
    private static void Kill(Policy mutant,Packet trigger){Assert(OracleDetects(mutant,trigger),"MUTANT_SURVIVED");mutants++;}
    private static T At<T>(IntPtr p) where T:struct{return (T)Marshal.PtrToStructure(p,typeof(T));}
    private static NativeCondition[] Conditions(FilterLease lease){int stride=Marshal.SizeOf(typeof(NativeCondition));return Enumerable.Range(0,(int)lease.Filter.Count).Select(i=>At<NativeCondition>(IntPtr.Add(lease.Filter.Conditions,i*stride))).ToArray();}
    private static void Run(){var r=Request();var p=Builder.Build(r);
        Case("valid_typed_request_and_eight_disjoint_denies",()=>{StaticVerifier.Verify(p);Assert(p.Filters.Count==8,"COUNT");});
        Case("deterministic_owner_keys_and_plan_digest",()=>Assert(Builder.Build(Request()).ApprovalHash==p.ApprovalHash,"DETERMINISM"));
        Case("different_host_inventory_owner_endpoint_change_digest",()=>{Assert(Builder.Build(Request(host:new string('c',64))).ApprovalHash!=p.ApprovalHash,"HOST_BINDING");Assert(Builder.Build(Request(inventory:new string('c',64))).ApprovalHash!=p.ApprovalHash,"INVENTORY_BINDING");Assert(Builder.Build(Request(owner:new Guid("22222222-2222-4222-8222-222222222222"))).Provider!=p.Provider,"OWNER_BINDING");Assert(Builder.Build(Request(port:54322)).ApprovalHash!=p.ApprovalHash,"PORT_BINDING");});
        Case("invalid_and_well_known_sid_rejected",()=>{foreach(var s in new[]{"S-1-5-18","S-1-5-32-544","S-1-5-21-1-2-3-500","S-1-5-21-0-2-3-1000","S-1-5-21-1-2-3-4294967296","S-1-5-21-01-2-3-1000","S-1-5-21-1-2-3-1000\n"})Throws(()=>Request(client:s));});
        Case("role_and_UI_identity_collision_rejected",()=>{Throws(()=>Request(broker:C));Throws(()=>Request(client:U));Throws(()=>Request(broker:U));});
        Case("client_broker_machine_prefix_mismatch_rejected",()=>Throws(()=>Request(broker:"S-1-5-21-404-505-606-1002")));
        Case("empty_owner_and_noncanonical_hashes_rejected",()=>{Throws(()=>Request(owner:Guid.Empty));Throws(()=>Request(host:"not-a-host-binding"));Throws(()=>Request(inventory:new string('A',64)));});
        Case("literal_remote_endpoint_only_no_DNS_or_proxy_fallback",()=>{foreach(var s in new[]{"example.invalid","::1","127.0.0.1","0.0.0.0","224.0.0.1","169.254.1.1","192.000.2.44","1.2.3.256","1.2.3.4\n"})Throws(()=>Request(remote:s));Throws(()=>Request(port:0));Throws(()=>Request(remotePort:0));});
        Case("other_profiles_never_strict_failure_fallback",()=>{Throws(()=>Request(profile:"DIRECT_ALLOWED"));Throws(()=>Request(profile:"APPROVED_PROXY"));Throws(()=>Request(profile:"STRICT_V2RAY_BROKER "));});
        Case("operator_attestation_never_security_authority",()=>{Throws(()=>Request(provenance:"VERIFIED"));Assert(OfflineBackend.Apply(p,r,p.ApprovalHash,Now).StartsWith("BLOCKED:"),"APPLY");});
        Case("stale_future_nonUTC_and_oversized_inventory_window",()=>{Throws(()=>r.Fresh(Now.AddMinutes(10)));Throws(()=>r.Fresh(Now.AddMinutes(-1)));Throws(()=>r.Fresh(DateTime.SpecifyKind(Now,DateTimeKind.Local)));Throws(()=>Request(expires:Now.AddMinutes(6)));});
        Case("approval_hash_and_modified_request_rejected",()=>{Throws(()=>StaticVerifier.Binding(p,r,new string('c',64),Now));Throws(()=>StaticVerifier.Binding(p,Request(port:54322),p.ApprovalHash,Now));});
        Case("attacker_rehash_does_not_make_modified_plan_valid",()=>{var q=Mutate(p,0,f=>Copy(f,key:new Guid("33333333-3333-4333-8333-333333333333")));Throws(()=>StaticVerifier.Binding(q,r,q.ApprovalHash,Now));});
