        Case("broker_or_BFE_failure_blocks_without_route_fallback",()=>{foreach(var failure in new[]{Observation.KnownFalse,Observation.Unknown}){var a=new Admission(failure,failure,Observation.Unknown,Observation.Unknown,Observation.Unknown,Observation.Unknown);Assert(!a.Allowed&&a.Blockers.Any(x=>x.StartsWith("BROKER_"))&&a.Blockers.Any(x=>x.StartsWith("BFE_")),"ADMISSION");}});
