        Case("foreign_block_and_empty_incomplete_graph_need_review",()=>{Assert(ArbitrationSurvey.Assess(new[]{new CompetingFilter(6,"BLOCK",1,1)},true)[1].Contains("AVAILABILITY_UNVERIFIED"),"BLOCK_AVAILABILITY");Assert(ArbitrationSurvey.Assess(new CompetingFilter[0],false).Contains("EFFECTIVE_GRAPH_INCOMPLETE"),"INCOMPLETE_GRAPH");});
        Case("delegated_SYSTEM_or_changed_identity_not_covered_by_SID_filters",()=>{Assert(PredicateInterpreter.Matches(p,new Packet("S-1-5-18",4,17,0xc000022c,53))==0,"DELEGATION_REQUIRES_SEPARATE_BOUNDARY");});
        Case("endpoint_boundary_positive_negative_controls",()=>{Assert(PredicateInterpreter.Matches(p,new Packet(C,4,6,0x7f000001,54321))==0,"CLIENT_EDGE");Assert(PredicateInterpreter.Matches(p,new Packet(B,4,6,0xc000022c,443))==0,"BROKER_EDGE");Assert(PredicateInterpreter.Matches(p,new Packet(C,4,6,0x7f000001,54322))==1,"OTHER_LOOPBACK_PORT");Assert(PredicateInterpreter.Matches(p,new Packet(C,4,6,0x7f000002,54321))==1,"OTHER_LOOPBACK_ADDRESS");Assert(PredicateInterpreter.Matches(p,new Packet(B,4,6,0xc000022d,443))==1,"SECONDARY_ENDPOINT");});
        Case("alternate_remote_all_octets_and_port_extremes_are_parameterized",()=>{var q=Builder.Build(Request(port:1,remote:"198.51.100.19",remotePort:65535));StaticVerifier.Verify(q);foreach(var x in new[]{new Packet(C,4,6,0x7f000001,1),new Packet(C,4,6,0x7f000001,54321),new Packet(B,4,6,0xc6336413,65535),new Packet(B,4,6,0xc000022c,443),new Packet(B,4,6,0xc6336413,65534)})Assert(PredicateInterpreter.Matches(q,x)==Expected(q.Request,x),"PARAMETERIZED_ENDPOINT_ORACLE");});
        Case("all_protocol_bytes_addresses_ports_families_roles_oracle",()=>{uint[] addresses={0,0x7f000001,0x7f000002,0xc000022c,0xc000022d,0xffffffff};ushort[] ports={0,1,53,443,54320,54321,54322,65535};foreach(var sid in new[]{C,B,U})foreach(int family in new[]{4,6})for(int proto=0;proto<256;proto++)foreach(uint address in addresses)foreach(ushort port in ports){var x=new Packet(sid,family,(byte)proto,address,port);Assert(PredicateInterpreter.Matches(p,x)==Expected(r,x),"ORACLE_MISMATCH");points++;}});
