        Case("mock_transaction_commit_and_idempotent_resume",()=>{var s=new MemoryStore();Assert(TransactionSimulation.Stage(s,p,p.ApprovalHash,Now).Status.StartsWith("MOCK_STAGED"),"STAGE");Assert(s.Count==10,"OBJECT_COUNT");Assert(TransactionSimulation.Stage(s,p,p.ApprovalHash,Now).Status.Contains("ALREADY_PRESENT"),"RESUME");Assert(s.Trace.Count(t=>t=="BEGIN")==1&&s.Count==10,"NO_DUPLICATES");});
