        Case("offline_entrypoint_does_not_reference_native_preview",()=>{Assert(typeof(OfflineTests).Assembly.GetReferencedAssemblies().All(a=>!a.Name.Contains("NativePreview")),"NATIVE_DEPENDENCY");Assert(typeof(Policy).Assembly.GetReferencedAssemblies().All(a=>!a.Name.Contains("NativePreview")),"CORE_NATIVE_DEPENDENCY");});
        Case("native_preview_metadata_only_no_public_API_or_entrypoint",()=>{var folder=AppDomain.CurrentDomain.BaseDirectory;Assembly.ReflectionOnlyLoadFrom(Path.Combine(folder,"Wua.Wfp.Core.dll"));Assembly.ReflectionOnlyLoadFrom(Path.Combine(folder,"Wua.Wfp.Abi.dll"));var a=Assembly.ReflectionOnlyLoadFrom(Path.Combine(folder,"Wua.Wfp.NativePreview.dll"));Assert(a.EntryPoint==null&&a.GetExportedTypes().Length==0,"EXPORTED_NATIVE_PATH");Assert(a.GetTypes().SelectMany(t=>t.GetMethods(BindingFlags.NonPublic|BindingFlags.Static)).Count(m=>(m.Attributes&MethodAttributes.PinvokeImpl)!=0)==15,"API_DECLARATIONS");Assert(a.GetCustomAttributesData().Any(x=>x.AttributeType.Name=="DefaultDllImportSearchPathsAttribute"&&(int)x.ConstructorArguments[0].Value==2048),"SYSTEM32_ONLY");});
        Case("immutable_policy_collections_reject_postapproval_mutation",()=>{try{((IList<Filter>)p.Filters).Add(p.Filters[0]);throw new Rejected("MUTABLE");}catch(NotSupportedException){}Assert(p.ApprovalHash==p.ComputeHash(),"IMMUTABLE_HASH");});
    }
    public static int Main(string[] args){
        // The only executable entrypoint: synthetic tests or BLOCKED. No apply mode.
        if(args.Length!=2||args[0]!="selftest"){Console.WriteLine("BLOCKED:OFFLINE_SELFTEST_ONLY");return 20;}
        string output=Path.GetFullPath(args[1]);string root=AppDomain.CurrentDomain.BaseDirectory;
        if(!output.StartsWith(root,StringComparison.OrdinalIgnoreCase)||File.Exists(output))return 21;
        Run();string json="{\"total\":"+(passed+failed)+",\"passed\":"+passed+",\"failed\":"+failed+",\"mutants_killed\":"+mutants+",\"oracle_points\":"+points+",\"native_WFP_API_calls\":0,\"network_probes\":0,\"scope\":\"managed synthetic and memory ABI only; NativePreview reflection-only metadata\",\"tests\":["+String.Join(",",Rows)+"]}";
        using(var stream=new FileStream(output,FileMode.CreateNew,FileAccess.Write))using(var writer=new StreamWriter(stream,new UTF8Encoding(false)))writer.WriteLine(json);
        Console.WriteLine("OFFLINE "+passed+"/"+(passed+failed)+" PASS; FAIL="+failed+"; mutants="+mutants+"; oracle_points="+points);return failed==0?0:1;
    }
